            color: var(--text-color);
            margin-left: 0.5rem;
            font-size: 1rem;
            font-weight: normal;
        }

        nav ul {
            display: flex;
            gap: 2rem;
        }

        nav a {
            font-weight: 500;
            color: var(--text-color);
        }

        nav a:hover, nav a.active {
            color: var(--primary-color);
        }

        .cta-btn {
            background-color: var(--accent-color);
            color: var(--white);
            padding: 0.5rem 1.5rem;
            border-radius: 20px;
            font-weight: bold;
        }

        .cta-btn:hover {
            background-color: #e68900;
            color: var(--white);
        }

        /* Hero Section */
        .hero {
            background: linear-gradient(135deg, var(--primary-color) 0%, var(--secondary-color) 100%);
            color: var(--white);
            padding: 4rem 2rem;
            text-align: center;
        }

        .hero h1 {
            font-size: 2.5rem;
            margin-bottom: 1rem;
        }

        .hero p {
            font-size: 1.2rem;
            margin-bottom: 2rem;
            opacity: 0.9;
        }

        .hero .btn-large {
            display: inline-block;
            background-color: var(--white);
            color: var(--primary-color);
            padding: 0.8rem 2rem;
            font-size: 1.1rem;
            font-weight: bold;
            border-radius: var(--border-radius);
            transition: transform 0.2s;
            margin-top: 1rem;
        }

        .hero .btn-large:hover {
            transform: translateY(-3px);
            box-shadow: 0 5px 15px rgba(0,0,0,0.2);
        }

        /* Features Section */
        .features {
            padding: 4rem 2rem;
            max-width: 1200px;
            margin: 0 auto;
            text-align: center;
        }

        .features h2 {
            margin-bottom: 3rem;
            color: var(--primary-color);
        }

        .feature-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 2rem;
        }

        .feature-card {
            padding: 2rem;
            background-color: var(--bg-light);
            border-radius: var(--border-radius);
        }

        .feature-icon {
            font-size: 2.5rem;
            margin-bottom: 1rem;
        }

        .feature-card h3 {
            margin-bottom: 1rem;
        }

        /* Stats Section */
        .stats {
            background-color: var(--bg-light);
            padding: 3rem 2rem;
            text-align: center;
        }

        .stats-container {
            max-width: 1200px;
            margin: 0 auto;
            display: flex;
            justify-content: space-around;
            flex-wrap: wrap;
            gap: 2rem;
        }

        .stat-item h3 {
            font-size: 2.5rem;
            color: var(--primary-color);
            margin-bottom: 0.5rem;
        }

        /* Footer */
        footer {
            background-color: #2c3e50;
            color: #bdc3c7;
            padding: 3rem 2rem;
            text-align: center;
        }

        .footer-content {
            max-width: 1200px;
            margin: 0 auto;
            display: flex;
            flex-direction: column;
            gap: 2rem;
        }

        .footer-links {
            display: flex;
            justify-content: center;
            gap: 2rem;
        }

        .footer-links a:hover {
            color: var(--white);
        }

        /* Responsive */
        @media (max-width: 768px) {
            .nav-container {
                flex-direction: column;
                gap: 1rem;
            }

            .hero h1 {
                font-size: 2rem;
            }

            nav ul {
                gap: 1rem;
                font-size: 0.9rem;
            }
        }
    </style>
</head>
